"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["85198"],{11434(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.regra_distribuicao_nao_encontrada","status":422,"titulo":"Regra de distribui\xe7\xe3o n\xe3o encontrada no cat\xe1logo de regras"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.regra_distribuicao_nao_encontrada","requisitos":[],"oQueAconteceu":["O `regraDistribuicaoCodigo`/`regraDistribuicaoVersao` de uma das\\ndistribui\xe7\xf5es de vagas do corpo do pedido n\xe3o existe no `rol_de_regras` \u2014 o\\ncat\xe1logo tipado de regras (Story #772) de onde v\xeam tanto a regra de\\ndistribui\xe7\xe3o em si (Lei 12.711 ou institucional) quanto, no ramo federal, a\\nregra de ajuste. `rol_de_regras` \xe9 um cat\xe1logo interno do pr\xf3prio m\xf3dulo\\nSele\xe7\xe3o, n\xe3o de Configura\xe7\xe3o \u2014 diferente da oferta de curso e das\\nmodalidades, que v\xeam de cadastros de outro m\xf3dulo. Esta \xe9 a segunda\\nresolu\xe7\xe3o do processamento de cada distribui\xe7\xe3o \u2014 roda logo depois da\\nresolu\xe7\xe3o da oferta de curso (ver\\n[`oferta_curso_nao_encontrada`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.oferta_curso_nao_encontrada)).","O processamento \xe9 sequencial por distribui\xe7\xe3o: a primeira distribui\xe7\xe3o do\\ncorpo do pedido cuja regra n\xe3o resolve interrompe a passada \u2014 as distribui\xe7\xf5es\\nseguintes do mesmo corpo do pedido n\xe3o chegam a ser conferidas, e a resposta traz\\ns\xf3 esta viola\xe7\xe3o, sem acumular com nenhuma outra."],"comoResolver":["Confirme, no cat\xe1logo de regras (`rol_de_regras`), que o c\xf3digo e a vers\xe3o\\ndeclarados existem. Se a regra foi descontinuada recentemente, ou o c\xf3digo\\nest\xe1 incorreto, corrija o corpo do pedido antes de reenviar.","Como o processamento para na primeira distribui\xe7\xe3o com problema, corrigir\\nesta e reenviar pode revelar uma nova falha numa distribui\xe7\xe3o seguinte do\\nmesmo corpo do pedido \u2014 n\xe3o \xe9 garantia de que o restante do corpo do pedido est\xe1 correto."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);